    'about' => [
        'meta_title' => 'Über uns — Unsere Mission und Geschichte',
        'meta_description' => 'Harmonivas Mission: professionelle Gehörbildung für jeden Musiker zugänglich machen — KI-gestützt, für Lernende, Lehrkräfte und Musikschulen.',
        'hero_badge' => 'Unsere Geschichte',
        'hero_title_a' => 'Wir bauen die Zukunft der',
        'hero_title_b' => 'Musikausbildung',
        'hero_subtitle' => 'Harmoniva wurde mit einer einzigen Mission gegründet — professionelle Gehörbildung für jeden Musiker auf diesem Planeten zugänglich zu machen.',
        'mission_p1' => 'Ob du als Anfänger dein erstes Instrument in die Hand nimmst oder als fortgeschrittener Spieler für die Aufnahmeprüfung am Konservatorium übst: Wir glauben, dass dein musikalisches Gehör dein wichtigstes Werkzeug ist. Technik lässt sich lehren, Theorie lässt sich auswendig lernen — aber ein fein geschultes Gehör verändert, wie du Musik hörst, fühlst und erschaffst.',
        'mission_p2' => 'Wir haben Harmoniva gebaut, weil wir eine Lücke sahen: Professionelle Gehörbildungssoftware war entweder unerschwinglich teuer, ärgerlich veraltet oder nur über eine Institution zugänglich. Jeder Musiker verdient Besseres.',
        'story_badge' => 'Wie alles begann',
        'story_title' => 'Wie Harmoniva entstanden ist',
        'story_p1' => 'Die Idee zu Harmoniva entstand in einem Überaum. Frustriert von sperriger, teurer Software und Einheitslehrplänen machten sich ein Musiker und ein Softwareentwickler daran, das Gehörbildungswerkzeug zu bauen, das sie sich immer gewünscht hatten — eines, das sich daran anpasst, wie du lernst, statt daran, wie die Software gebaut wurde.',
        'story_p2' => 'Nach Monaten der Recherche und vielen Gesprächen mit Musiklehrkräften, Konservatoriumsstudierenden und autodidaktischen Musikern weltweit zeichnete sich ein klares Bild ab: Die größte Hürde für gute Gehörbildung war weder Motivation noch Talent. Es war der Zugang. Zugang zu hochwertigen Übungen, zu strukturierten Lernpfaden und zu intelligentem Feedback, das sich an deine konkreten Schwächen anpasst.',
        'story_p3' => 'Harmoniva startete 2024 mit einer kleinen Auswahl an Kernübungen und einem großen Anspruch. Indem wir KI direkt in das Lernerlebnis integrierten, wurde es für jeden Musiker möglich — unabhängig von Budget oder Wohnort —, wie ein Konservatoriumsstudent zu trainieren. Heute nutzen Musiker in über 30 Ländern Harmoniva täglich, um ihre Intervalle, Akkorde, Rhythmen und ihr melodisches Gedächtnis zu schärfen.',
        'mission_card_title' => 'Unsere Mission',
        'mission_card_subtitle' => 'Was uns jeden Tag antreibt',
        'mission_card_quote' => '„Professionelle Gehörbildung für jeden Musiker auf diesem Planeten zugänglich zu machen — unabhängig davon, wo er lebt, was er sich leisten kann oder wo er auf seinem musikalischen Weg steht."',
        'vision_card_title' => 'Unsere Vision',
        'vision_card_subtitle' => 'Wohin wir wollen',
        'vision_card_text' => 'Eine Welt, in der KI-gestützte Musikausbildung die Kluft zwischen autodidaktischen Musikern und denen mit Zugang zu erstklassigen Konservatorien schließt.',
        'values_badge' => 'Wofür wir stehen',
        'values_title' => 'Unsere Grundwerte',
        'value_innovation_title' => 'Innovation',
        'value_innovation_desc' => 'Wir geben uns nicht mit „gut genug" zufrieden. Wir loten laufend aus, wie KI, adaptives Lernen und modernes UX Gehörbildung wirksamer, fesselnder und persönlicher machen können.',
        'value_accessibility_title' => 'Zugänglichkeit',
        'value_accessibility_desc' => 'Gute Gehörbildung darf kein Privileg sein. Wir bieten einen großzügigen kostenlosen Tarif, unterstützen 15 Sprachen und gestalten jede Funktion mit Blick auf Inklusion — von Farbkontrasten bis zur Tastaturbedienung.',
        'value_excellence_title' => 'Exzellenz',
        'value_excellence_desc' => 'Jede Übung, jedes Feedback, jede Interaktion in der Oberfläche entsteht mit Sorgfalt. Wir halten uns an denselben Maßstab, den unsere Nutzer in ihrer Musik anlegen.',
        'value_community_title' => 'Gemeinschaft',
        'value_community_desc' => 'Musiker wachsen gemeinsam. Wir bauen Funktionen, die Lehrkräfte, Schulen und Lernende als Ökosystem tragen — nicht als Ansammlung isolierter Nutzer.',
        'stat_1_value' => '10.000+',
        'stat_1_label' => 'aktive Musiker',
        'stat_2_value' => '15+',
        'stat_2_label' => 'Übungstypen',
        'stat_3_value' => '15',
        'stat_3_label' => 'unterstützte Sprachen',
        'stat_4_value' => 'KI',
        'stat_4_label' => 'gestützte Lernpfade',
        'team_badge' => 'Das Team',
        'team_title' => 'Von Musikern für Musiker gebaut',
        'team_p1' => 'Alle, die an Harmoniva arbeiten, kennen die Frustration, das eigene Gehör ohne die richtigen Werkzeuge entwickeln zu wollen. Wir sind Interpreten, Komponisten und Musikpädagogen, die zufällig auch gern Software bauen. Diese Kombination bedeutet: Wir verstehen, was Musiker wirklich brauchen — nicht, was sich in einer Produktdemo gut macht.',
        'team_p2' => 'Wir halten unser Team klein und fokussiert. Uns ist eine Funktion lieber, die Musikern beim Üben wirklich hilft, als zehn Funktionen, die nur Häkchen setzen. Jede Entscheidung — von der Auswahl der Übungen bis zur Darstellung des Feedbacks — beruht auf echter musikalischer Erfahrung und dem laufenden Austausch mit unserer Community.',
        'cta_title' => 'Bereit, dein Gehör zu trainieren?',
