        's12_use_1' => 'Öffne :assignments, um jedes Übungsset zu sehen, das deine Lehrkraft oder Schule geschickt hat — drücke Start, und dein Ergebnis wird automatisch zurückgemeldet.',
        's12_use_1_assignments' => 'Aufgaben',
        's12_use_2' => 'Nutze :messages, um Fragen zu stellen und geteilte Materialien zu erhalten — Dokumente, Artikel und Videos deiner Lehrkraft.',
        's12_use_2_messages' => 'Nachrichten',
