    'refund' => [
        'meta_title' => 'Rückerstattungsrichtlinie',
        'meta_description' => 'Rückerstattungsrichtlinie von Harmoniva: :days Tage Geld-zurück-Garantie auf Premium, Antragsweg, Widerrufsrecht und Bearbeitungsdauer.',
        'hero_title' => 'Rückerstattungsrichtlinie',
        'updated' => 'Zuletzt aktualisiert: 31. Juli 2026',
        'summary_title' => 'Die Kurzfassung',
        'summary_li1' => 'Teste Premium zuerst :trial Tage kostenlos — ohne Karte.',
        'summary_li2' => 'Für Premium bezahlt und es dir anders überlegt? Melde dich innerhalb von :days Tagen nach der Abbuchung, und du bekommst alles zurück.',
        'summary_li3' => 'Das gilt auch für eine ungewollte Jahresverlängerung, sofern du Premium seit der Verlängerung nicht genutzt hast.',
        'summary_li4' => 'Verbraucher in der EU, im Vereinigten Königreich und in der Türkei behalten zusätzlich ihre gesetzlichen Widerrufsrechte.',
        'box_title' => ':days Tage Geld-zurück-Garantie',
        'box_text' => 'Wenn Harmoniva Premium nichts für dich ist, schreib uns innerhalb von :days Tagen nach deiner Zahlung, und wir erstatten den vollen Betrag. Du musst nichts begründen und vorher nichts kündigen — die Kündigung übernehmen wir im Rahmen der Rückerstattung.',
        'commit_title' => 'Unser Versprechen zur Kundenzufriedenheit',
        'commit_p1' => 'Wir haben Harmoniva gebaut, weil wir aufrichtig daran glauben, was es für Musiker leistet. Wenn du abonnierst und feststellst, dass es nicht passt, wollen wir dein Geld nicht behalten. Diese Richtlinie ist bewusst fair, konkret und leicht umsetzbar formuliert.',
        'commit_p2' => 'Wir stehen auch hinter dem Produkt. Wenn etwas nicht wie erwartet funktioniert oder der Dienst nicht hält, was er verspricht, melde dich, bevor du eine Rückerstattung beantragst — unser Support löst das Problem oft in Minuten, und wir behalten lieber dich als deine Zahlung.',
        'trial_title' => 'Testen, bevor du zahlst',
        'trial_p1' => 'Jedes Konto startet im kostenlosen Tarif, der nie abläuft und nie nach einer Karte fragt. Zusätzlich kann jeder Nutzer eine kostenlose :trial-tägige Premium-Testphase in Anspruch nehmen — voller Zugriff, keine Zahlungsdaten nötig, und sie endet einfach von selbst.',
        'trial_p2' => 'Weil dir die Testphase das vollständige Premium-Erlebnis gibt, bevor Geld fließt, lassen sich die meisten Rückerstattungsanfragen ganz vermeiden. Eine Testphase ist kostenlos, es gibt also nichts zu erstatten.',
        'g_title' => ':days Tage Geld-zurück-Garantie',
        'g_intro' => 'Du hast Anspruch auf eine <strong>vollständige Rückerstattung</strong> einer Premium-Zahlung, wenn du dich innerhalb von <strong>:days Kalendertagen</strong> nach dieser Abbuchung meldest. Das umfasst:',
        'g_li1' => 'Deine erste monatliche Premium-Zahlung, in jeder Tarifstufe (Lernende, Lehrkräfte oder Schule).',
        'g_li2' => 'Deine erste jährliche Premium-Zahlung, in jeder Tarifstufe.',
        'g_li3' => 'Eine automatische <strong>Jahresverlängerung</strong>, sofern du seit dem Verlängerungsdatum keine Premium-Funktionen genutzt hast. Das ist die Abbuchung, die Menschen am häufigsten überrascht — wir behandeln sie deshalb wie eine Erstzahlung.',
        'g_li4' => 'Jede irrtümliche Abbuchung — eine Doppelzahlung, ein Tarif, den du nicht gewählt hast, oder eine Abbuchung nach bereits erfolgter Kündigung. Diese erstatten wir immer vollständig, wann immer sie dir auffallen.',
        'g_p1' => 'Die Frist von :days Tagen beginnt am Tag der Zahlungsabwicklung, nicht am Tag deiner ersten Anmeldung. Wird deine Zahlung am 1. Juni verarbeitet, endet die Frist mit Ablauf des 15. Juni.',
        'g_p2' => 'Die Garantie gilt je Abbuchung, nicht je Konto — sie ist aber kein Weg, Premium dauerhaft gratis zu nutzen: Wir können eine wiederholte Anfrage von einem Konto ablehnen, dem für denselben Tarif bereits erstattet wurde. Sollte das je auf dich zutreffen, sagen wir es dir klar und schriftlich, statt still abzulehnen.',
        'law_title' => 'Deine gesetzlichen Rechte',
        'law_p1' => 'Nichts in dieser Richtlinie schränkt Rechte ein, die dir nach dem Verbraucherrecht deines Wohnorts zustehen. Wo diese Rechte weiter reichen als die obige Garantie, gilt das Gesetz.',
        'law_li1' => '<strong>Europäische Union & Vereinigtes Königreich</strong>: Verbraucher haben bei Fernabsatzverträgen ein 14-tägiges Widerrufsrecht. Indem du Premium unmittelbar nach dem Kauf nutzt, verlangst du von uns, mit der Leistung innerhalb dieser Frist zu beginnen; du kannst dennoch binnen 14 Tagen widerrufen, und soweit wir die Leistung bereits erbracht haben, dürfen wir einen anteiligen Betrag für das Genutzte einbehalten. In der Praxis erstatten wir vollständig und ziehen nichts ab.',
        'law_li2' => '<strong>Türkei</strong>: Nach dem Verbraucherschutzgesetz (Nr. 6502) und der Fernabsatzverordnung hast du ein 14-tägiges Widerrufsrecht. Digitale Inhalte, die mit deiner Zustimmung sofort bereitgestellt werden, sind davon üblicherweise ausgenommen — wir verzichten auf diese Ausnahme und erkennen den Widerruf zu den obigen Bedingungen dennoch an.',
        'law_li3' => '<strong>Vereinigte Staaten</strong>: Rückerstattungsrechte unterscheiden sich je Bundesstaat, und manche Staaten geben Käufern zusätzliche Kündigungsrechte. Diese Richtlinie gilt landesweit als Mindeststandard; jedes weitergehende Recht nach dem Recht deines Bundesstaats bleibt unberührt.',
        'law_li4' => '<strong>Überall sonst</strong>: Wenn dein örtliches Verbraucherrecht dir eine längere Frist oder ein weiter reichendes Recht als diese Richtlinie gibt, sag uns Bescheid, und wir wenden es an.',
        'law_p2' => 'Um ein gesetzliches Widerrufsrecht auszuüben, genügt eine formlose E-Mail mit der Erklärung, dass du vom Vertrag zurücktrittst — ein bestimmtes Formular oder eine bestimmte Formulierung ist nicht erforderlich.',
        'req_title' => 'So beantragst du eine Rückerstattung',
        'req_intro' => 'Eine Rückerstattung zu beantragen ist einfach und dauert weniger als zwei Minuten:',
        'req_s1_title' => 'Schreib uns innerhalb der Frist',
        'req_s1_desc' => 'Sende eine E-Mail an :email mit dem Betreff <strong>„Refund Request"</strong>.',
        'req_s2_title' => 'Nenne deine Konto-E-Mail',
        'req_s2_desc' => 'Teile uns die E-Mail-Adresse deines Harmoniva-Kontos und das ungefähre Zahlungsdatum mit. Wenn du schreiben möchtest, was nicht gepasst hat, lesen wir jedes Wort — das ist aber freiwillig und beeinflusst die Entscheidung nie.',
        'req_s3_title' => 'Wir bestätigen und bearbeiten',
        'req_s3_desc' => 'Wir bestätigen deine Anfrage innerhalb von 1 Werktag und beginnen sofort mit der Bearbeitung. Wie lange das Geld unterwegs ist, steht unten unter „Ablauf & Dauer der Rückerstattung".',
        'req_note' => 'Du musst dein Abo vor der Anfrage nicht kündigen — die Kündigung gehört zum Rückerstattungsprozess. Wenn du vorher selbst kündigst, ist das ebenfalls in Ordnung: Eine Kündigung verwirkt dein Rückerstattungsrecht nicht, solange du dich innerhalb der Frist meldest.',
        'nr_title' => 'Was nicht abgedeckt ist',
        'nr_intro' => 'Außerhalb der oben genannten Fälle sind Rückerstattungen in diesen Situationen in der Regel nicht möglich:',
        'nr_li1' => '<strong>Anfragen nach Ablauf der :days-Tage-Frist</strong>: Ist die Frist abgelaufen, ist eine Zahlung nicht mehr erstattungsfähig — es sei denn, es liegt ein Abrechnungsfehler oder ein dokumentiertes Versäumnis auf unserer Seite vor, das wir unabhängig vom Zeitpunkt beheben.',
        'nr_li2' => '<strong>Genutzte Monatsverlängerungen</strong>: Wird eine monatliche Verlängerung abgebucht und hast du im neuen Zeitraum mit Premium geübt, erstatten wir sie nicht. Du kannst jederzeit kündigen, um die nächste zu stoppen.',
        'nr_li3' => '<strong>Anteilige Zeiträume</strong>: Wir rechnen einen ungenutzten Rest nicht anteilig ab. Wenn du mitten im Zyklus kündigst, behältst du den vollen Premium-Zugriff bis zum Ende des bezahlten Zeitraums — es geht also nichts verloren.',
        'nr_li4' => '<strong>Wegen Regelverstößen geschlossene Konten</strong>: Kündigen wir ein Konto wegen eines Verstoßes gegen unsere Nutzungsbedingungen, wird der verbleibende Abowert nicht erstattet.',
        'nr_li5' => '<strong>Kostenloser Tarif und Testphase</strong>: Der kostenlose Tarif und die :trial-tägige Testphase kosten nichts, also gibt es nichts zu erstatten.',
        'nr_p1' => 'Diese Liste ist keine Mauer. Wenn du glaubst, einen berechtigten Anspruch außerhalb davon zu haben — eine nie autorisierte Abbuchung, ein technisches Problem, das dich am Nutzen des Bezahlten gehindert hat, eine Zahlung durch ein Familienmitglied ohne dein Wissen — schreib uns. Solche Fälle prüfen wir einzeln und entscheiden sie nach Treu und Glauben.',
        'app_title' => 'Käufe über den App Store oder Google Play',
        'app_p1' => 'Wenn du in einer mobilen Harmoniva-App per In-App-Kauf abonnierst, ist Apple bzw. Google der Händler für diese Transaktion — wir erhalten deine Zahlungsdaten nie und können sie selbst nicht erstatten.',
        'app_li1' => '<strong>Apple App Store</strong>: Beantrage eine Rückerstattung unter <em>reportaproblem.apple.com</em> oder über die Einstellungen deines Geräts. Apple entscheidet darüber nach eigener Richtlinie.',
        'app_li2' => '<strong>Google Play</strong>: Beantrage eine Rückerstattung über deinen Google-Play-Bestellverlauf oder den Google-Play-Support. Google entscheidet darüber nach eigener Richtlinie.',
        'app_li3' => '<strong>Abo verwalten</strong>: Ein In-App-Abo muss außerdem in dem Store-Konto gekündigt werden, das es gekauft hat — eine Kündigung innerhalb von Harmoniva stoppt die Store-Abrechnung nicht.',
        'app_p2' => 'Lehnt der Store deine Anfrage ab und glaubst du, dass die obige :days-Tage-Garantie greifen sollte, melde dich mit deiner Bestellnummer bei uns. Eine Store-Abbuchung können wir nicht rückgängig machen, aber wir können dir auf unsere Kosten gleichwertigen Premium-Zugang oder ein Guthaben einräumen, damit du nicht draufzahlst.',
        'app_p3' => 'Auf unserer Website gekaufte Abos werden von uns abgerechnet und vollständig nach dieser Richtlinie behandelt.',
        'tl_title' => 'Ablauf & Dauer der Rückerstattung',
        'tl_intro' => 'Sobald eine Rückerstattung genehmigt ist:',
        'tl_li1' => 'Wir kündigen das Abo und stellen das Konto auf den kostenlosen Tarif um. Dein Übungsverlauf, dein Fortschritt und gespeicherte Vorlagen bleiben erhalten — nur die Premium-Funktionen enden.',
        'tl_li2' => 'Die Rückerstattung geht über unseren Zahlungsdienstleister an das ursprüngliche Zahlungsmittel zurück. An eine andere Karte oder ein anderes Konto können wir sie nicht senden.',
        'tl_li3' => 'Du erhältst eine E-Mail, die die Rückerstattung und den Betrag bestätigt.',
        'tl_box_title' => 'Übliche Dauer: 5–10 Werktage',
        'tl_box_desc' => 'Rückerstattungen erscheinen meist innerhalb von 5–10 Werktagen nach unserem Bearbeitungsdatum auf deiner Karten- oder Kontoabrechnung. Den genauen Zeitpunkt bestimmt dein Kartenherausgeber oder deine Bank; er liegt außerhalb unserer Kontrolle. Manche Banken brauchen bis zu 14 Werktage, einige zeigen die Rückerstattung mit dem ursprünglichen Buchungsdatum an.',
        'tl_note' => 'Ist die Rückerstattung nach 14 Werktagen nicht angekommen, frag zuerst bei deiner Bank nach und melde dich dann bei uns — wir haken bei unserem Zahlungsdienstleister nach und schicken dir die Transaktionsreferenz.',
        'cb_title' => 'Rückbuchungen & Zahlungsstreitigkeiten',
        'cb_p1' => 'Wenn du eine Abbuchung nicht zuordnen kannst, schreib uns bitte, bevor du bei deiner Bank einen Streitfall eröffnest. Fast jeder Fall, den wir sehen, ist eine Jahresverlängerung oder der Kauf eines Familienmitglieds, und wir können ihn meist am selben Tag erstatten — deutlich schneller als eine Rückbuchung, die üblicherweise 6–12 Wochen dauert.',
        'cb_p2' => 'Wird eine Rückbuchung eröffnet, antworten wir mit unseren Transaktionsunterlagen. Solange ein Streitfall offen ist, können wir den Premium-Zugang des Kontos aussetzen, bis er geklärt ist; ein Konto mit einer Rückbuchung muss den offenen Betrag gegebenenfalls ausgleichen, bevor es erneut abonnieren kann. Streitfallgebühren geben wir nicht an Nutzer weiter.',
        'tp_title' => 'Unterricht, Lehrkräfte und Schullizenzen',
        'tp_p1' => 'Harmoniva bringt Lernende mit unabhängigen Lehrkräften und Musikschulen zusammen, ist aber nicht Vertragspartei einer Unterrichtsvereinbarung zwischen ihnen. Honorare für Privatunterricht, Termine oder Studiengebühren, die über eine Lehrkraft oder Schule vereinbart werden, gehen direkt an diese Lehrkraft bzw. Schule nach deren eigenen Bedingungen — wir ziehen sie nicht ein, und diese Richtlinie deckt sie nicht ab. Frag deine Lehrkraft oder Schule nach ihren Storno- und Rückerstattungsbedingungen.',
        'tp_p2' => 'Diese Richtlinie deckt die Harmoniva-Abos selbst ab, einschließlich der bei uns gekauften Lehrkräfte- und Schultarife. Kauft eine Schule oder Einrichtung Plätze für ihre Mitglieder im Rahmen einer gesonderten schriftlichen Vereinbarung, gelten deren Rückerstattungsbedingungen und gehen dieser Seite vor.',
        'tp_p3' => 'Aktionsguthaben, geschenkte oder kostenlos gewährte Premium-Zeiträume, Gutscheine und Rabatte haben keinen Barwert und sind weder erstattungs- noch in Geld umtauschfähig.',
        'cur_title' => 'Währung, Steuern und Gebühren',
        'cur_p1' => 'Preise werden in US-Dollar berechnet, sofern beim Bezahlvorgang nichts anderes angegeben ist. Rückerstattungen erfolgen in der ursprünglichen Währung und über den ursprünglich abgebuchten Betrag, einschließlich der von uns erhobenen Steuer.',
        'cur_p2' => 'Läuft deine Karte in einer anderen Währung, kann der zurückkommende Betrag leicht von dem abweichen, der abgebucht wurde, weil deine Bank bei jeder Umrechnung ihren eigenen Kurs anwendet. Von deiner Bank erhobene Auslandseinsatzentgelte legt deine Bank fest und können von uns nicht erstattet werden.',
        'ch_title' => 'Änderungen dieser Richtlinie',
        'ch_p1' => 'Wir können diese Rückerstattungsrichtlinie anpassen, wenn sich der Dienst verändert. Maßgeblich für eine Zahlung ist die Fassung, die zum Zeitpunkt der Zahlung galt — eine spätere Änderung kann ein bereits bestehendes Rückerstattungsrecht also nie schmälern. Wesentliche Änderungen kündigen wir vor Inkrafttreten per E-Mail oder Hinweis in der App an, und das Datum „Zuletzt aktualisiert" oben auf dieser Seite entspricht stets der aktuellen Fassung.',
        'contact_title' => 'Kontakt',
        'contact_intro' => 'Fragen zu einer Rückerstattung oder das Gefühl, dass eine Abbuchung falsch ist? Schreib uns — jede Nachricht wird von einem Menschen gelesen.',
        'contact_box_title' => 'Support für Rückerstattung & Abrechnung',
