    'terms' => [
        'meta_title' => 'Nutzungsbedingungen',
        'meta_description' => 'Nutzungsbedingungen von Harmoniva. Bitte lies diese Bedingungen sorgfältig, bevor du unsere KI-gestützte Gehörbildungsplattform nutzt.',
